import * as Fs from "node:fs/promises"
import * as Path from "node:path"
import * as Digest from "./Digest.ts"

/**
 * Writes `npmrc` as the `.npmrc` of a fresh project and resolves with its digest.
 */
export const digestNpmrc = async (npmrc: string) => {
  const projectRoot = await Fs.mkdtemp(Path.join("build", "npmrc-"))
  await Fs.writeFile(Path.join(projectRoot, ".npmrc"), npmrc, "utf8")
  return Digest.of(npmrc)
}

import { createServer } from "node:http"
import * as Layer from "./Layer.ts"

export interface ServerOptions {
  readonly port: number
}

/** Serves the control API on the options' port. */
export const layerServer = (options: ServerOptions) => Layer.make(() => createServer().listen(options.port))

export const defaultOptions: ServerOptions = { port: 4000 }

import { readFileSync } from "node:fs"

export interface Row {
  readonly id: string
}

export function readRows<T extends Row>(path: string, limit = 10) {
  return (JSON.parse(readFileSync(path, "utf8")) as ReadonlyArray<T>).slice(0, limit)
}
